#!/usr/bin/env bash
# Runs the label-filter experiment (six students: three training sets x two seeds), one at a time,
# on whichever GPU is free. The machine is shared: before each run it waits until some GPU has been
# below 30% use and 20 GB memory for three checks in a row, a minute apart. A run already trained
# and scored is skipped, and an unfinished one resumes from its last checkpoint, so the queue can
# simply be started again after a restart.
#
#   bash scripts/run_detached.sh label_filter bash scripts/signal_rebuild/label_filter_queue.sh
#
# Do NOT edit this file while it is running.
set -u
BASE=/data/brhanu/thesis_project
PY=$BASE/.venv/bin/python3
OUT=$BASE/results/signal_rebuild/label_filter
cd "$BASE/scripts/signal_rebuild"
say() { echo "[$(date '+%F %T')] $*"; }

free_gpu() {
  local streak=0 g=""
  while true; do
    g=$(nvidia-smi --query-gpu=index,utilization.gpu,memory.used --format=csv,noheader,nounits |
        awk -F', ' '$2 < 30 && $3 < 20000 {print $1; exit}')
    if [ -n "$g" ]; then streak=$((streak + 1)); else streak=0; fi
    [ "$streak" -ge 3 ] && { echo "$g"; return; }
    sleep 60
  done
}

finished() {
  local w=$BASE/runs/detect/label_filter_$1_s$2/weights/last.pt
  [ -f "$w" ] && "$PY" -c "import torch, sys; ck = torch.load('$w', map_location='cpu', weights_only=False); sys.exit(0 if ck.get('epoch', 0) == -1 else 1)" 2>/dev/null
}

for seed in 20260919 20261007; do
  for v in all random consensus; do
    if [ -f "$OUT/detections_${v}_s${seed}.json" ]; then say "$v seed $seed already scored"; continue; fi
    say "$v seed $seed: waiting for a free GPU"
    g=$(free_gpu); say "$v seed $seed: GPU $g"
    tries=0
    until finished "$v" "$seed"; do
      tries=$((tries + 1)); [ "$tries" -gt 3 ] && { say "$v seed $seed unfinished after 3 tries; skipping"; continue 2; }
      last=$BASE/runs/detect/label_filter_${v}_s${seed}/weights/last.pt
      if [ -f "$last" ]; then
        "$PY" -c "from ultralytics import YOLO; YOLO('$last').train(resume=True, device='$g')"
      else
        "$PY" run_label_filter_experiment.py train --variant "$v" --seed "$seed" --device "$g"
      fi
    done
    CUDA_VISIBLE_DEVICES=$g "$PY" run_label_filter_experiment.py score --variant "$v" --seed "$seed" --device 0 &&
      say "$v seed $seed scored"
    "$PY" run_label_filter_experiment.py summary
  done
done
say "queue done"
